class Solution:
    def removeInvalidParentheses(self, s: str) -> list[str]:
        def valid(text):
            balance = 0
            for ch in text:
                if ch == '(': balance += 1
                elif ch == ')':
                    balance -= 1
                    if balance < 0: return False
            return balance == 0
        level = {s}
        while level:
            good = [text for text in level if valid(text)]
            if good: return good
            next_level = set()
            for text in level:
                for i, ch in enumerate(text):
                    if ch not in '()': continue
                    if i and text[i] == text[i-1]: continue
                    next_level.add(text[:i] + text[i+1:])
            level = next_level
        return ['']

import java.util.*;
class Solution {
    private boolean valid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') balance++;
            else if (c == ')' && --balance < 0) return false;
        }
        return balance == 0;
    }
    public List<String> removeInvalidParentheses(String s) {
        Set<String> level = new HashSet<>(); level.add(s);
        while (!level.isEmpty()) {
            List<String> good = new ArrayList<>();
            for (String cur : level) if (valid(cur)) good.add(cur);
            if (!good.isEmpty()) return good;
            Set<String> next = new HashSet<>();
            for (String cur : level) for (int i=0;i<cur.length();i++) {
                char c=cur.charAt(i); if (c!='(' && c!=')') continue;
                if (i>0 && cur.charAt(i)==cur.charAt(i-1)) continue;
                next.add(cur.substring(0,i)+cur.substring(i+1));
            }
            level=next;
        }
        return List.of("");
    }
}

