class NumArray:
    def __init__(self, nums: list[int]):
        self.nums=nums[:]; self.n=len(nums); self.bit=[0]*(self.n+1)
        for i,v in enumerate(nums): self._add(i+1,v)
    def _add(self,i,delta):
        while i<=self.n: self.bit[i]+=delta; i+=i&-i
    def update(self,index: int,val: int)->None:
        delta=val-self.nums[index]; self.nums[index]=val; self._add(index+1,delta)
    def _sum(self,i):
        total=0
