class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n<=2: return list(range(n))
        graph=[set() for _ in range(n)]
        for a,b in edges: graph[a].add(b); graph[b].add(a)
        leaves=deque(i for i in range(n) if len(graph[i])==1)
        remaining=n
        while remaining>2:
            size=len(leaves); remaining-=size
            for _ in range(size):
                leaf=leaves.popleft(); neighbor=graph[leaf].pop(); graph[neighbor].remove(leaf)
                if len(graph[neighbor])==1: leaves.append(neighbor)
        return list(leaves)

import java.util.*;
class Solution {
    public List<Integer> findMinHeightTrees(int n,int[][] edges) {
        if(n<=2){List<Integer> a=new ArrayList<>();for(int i=0;i<n;i++)a.add(i);return a;}
        List<Set<Integer>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new HashSet<>());
        for(int[] e:edges){g.get(e[0]).add(e[1]);g.get(e[1]).add(e[0]);}
        Queue<Integer> q=new ArrayDeque<>();for(int i=0;i<n;i++)if(g.get(i).size()==1)q.offer(i);
        int remain=n;while(remain>2){int size=q.size();remain-=size;for(int z=0;z<size;z++){int leaf=q.poll();int nei=g.get(leaf).iterator().next();g.get(nei).remove(leaf);g.get(leaf).clear();if(g.get(nei).size()==1)q.offer(nei);}}
        return new ArrayList<>(q);
    }
}

class Solution:
